// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 numberVal,
        uint64 timestampVal,
        uint256 basefeeVal,
        bytes32 hashVal,
        uint64 seqVal,
        bytes32 batcherVal,
        uint256 overheadVal,
        uint256 scalarVal
    ) public {
        vm.prank(DEPOSITOR);
        c.setL1BlockValues(numberVal, timestampVal, basefeeVal, hashVal, seqVal, batcherVal, overheadVal, scalarVal);
        assertTrue(c.number() == numberVal);
    }
}
